// Package toml parses TOML documents into the decoder's tagged JSON model.
package toml

import (
	"fmt"
	"strconv"
	"strings"
)

// Value is a scalar TOML value represented in the JSON contract.
type Value struct {
	Type  string `json:"type"`
	Value string `json:"value"`
}

// Document is the root TOML table.
type Document map[string]any

// Decode parses a TOML document and returns its tagged representation.
func Decode(input string) (Document, error) {
	document := make(Document)
	for lineNumber, line := range strings.Split(input, "\n") {
		line = strings.TrimSpace(stripComment(line))
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "[") {
			return nil, fmt.Errorf("line %d: tables are not implemented", lineNumber+1)
		}
		key, rawValue, ok := strings.Cut(line, "=")
		if !ok {
			return nil, fmt.Errorf("line %d: expected key and value", lineNumber+1)
		}
		key = strings.TrimSpace(key)
		if key == "" || strings.ContainsAny(key, " \t") {
			return nil, fmt.Errorf("line %d: invalid key", lineNumber+1)
		}
		if _, exists := document[key]; exists {
			return nil, fmt.Errorf("line %d: duplicate key %q", lineNumber+1, key)
		}
		value, err := parseValue(strings.TrimSpace(rawValue))
		if err != nil {
			return nil, fmt.Errorf("line %d: %w", lineNumber+1, err)
		}
		document[key] = value
	}
	return document, nil
}

func stripComment(line string) string {
	quoted := false
	for i, r := range line {
		if r == '"' && (i == 0 || line[i-1] != '\\') {
			quoted = !quoted
		}
		if r == '#' && !quoted {
			return line[:i]
		}
	}
	return line
}

func parseValue(raw string) (Value, error) {
	if raw == "true" || raw == "false" {
		return Value{Type: "bool", Value: raw}, nil
	}
	if strings.HasPrefix(raw, "\"") && strings.HasSuffix(raw, "\"") && len(raw) >= 2 {
		value, err := strconv.Unquote(raw)
		if err != nil {
			return Value{}, fmt.Errorf("invalid string")
		}
		return Value{Type: "string", Value: value}, nil
	}
	if _, err := strconv.ParseInt(raw, 10, 64); err == nil {
		return Value{Type: "integer", Value: raw}, nil
	}
	return Value{}, fmt.Errorf("unsupported value")
}
package toml

import (
	"encoding/json"
	"reflect"
	"testing"
)

func TestDecodeBasicDocument(t *testing.T) {
	got, err := Decode("answer = 42\nready = true\nlabel = \"ok\"\n")
	if err != nil {
		t.Fatalf("Decode returned error: %v", err)
	}
	want := Document{
		"answer": Value{Type: "integer", Value: "42"},
		"ready":  Value{Type: "bool", Value: "true"},
		"label":  Value{Type: "string", Value: "ok"},
	}
	if !reflect.DeepEqual(got, want) {
		t.Fatalf("Decode = %#v, want %#v", got, want)
	}
}

func TestDecodeEmptyDocumentIsEmptyObject(t *testing.T) {
	got, err := Decode("# comment\n\n")
	if err != nil {
		t.Fatalf("Decode returned error: %v", err)
	}
	if len(got) != 0 {
		t.Fatalf("Decode returned %d keys, want empty document", len(got))
	}
}

func TestDecodeMalformedDocumentReturnsError(t *testing.T) {
	if _, err := Decode("answer = [\n"); err == nil {
		t.Fatal("Decode returned success for malformed document")
	}
}

func TestValueUsesTaggedJSONSchema(t *testing.T) {
	encoded, err := json.Marshal(Value{Type: "integer", Value: "42"})
	if err != nil {
		t.Fatalf("Marshal returned error: %v", err)
	}
	if string(encoded) != `{"type":"integer","value":"42"}` {
		t.Fatalf("Marshal = %s, want tagged value JSON", encoded)
	}
}
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"os"

	"github.com/owner/toml-decoder/internal/toml"
)

func main() {
	if err := run(os.Stdin, os.Stdout, os.Stderr); err != nil {
		os.Exit(1)
	}
}

func run(input io.Reader, output, diagnostics io.Writer) error {
	source, err := io.ReadAll(input)
	if err != nil {
		_, _ = fmt.Fprintln(diagnostics, err)
		return err
	}
	tagged, err := toml.Decode(string(source))
	if err != nil {
		_, _ = fmt.Fprintln(diagnostics, err)
		return err
	}
	if err := json.NewEncoder(output).Encode(tagged); err != nil {
		_, _ = fmt.Fprintln(diagnostics, err)
		return err
	}
	return nil
}
