func parseMultiline(s string, pos int, quote byte) (string, int, error) {
	i := pos + 3
	if i < len(s) && s[i] == '\r' {
		i++
	}
	if i < len(s) && s[i] == '\n' {
		i++
	}
	var b strings.Builder
	for i < len(s) {
		if i+2 < len(s) && s[i] == quote && s[i+1] == quote && s[i+2] == quote {
			return b.String(), i + 3, nil
		}
		if quote == '"' && s[i] == '\\' {
			if i+1 < len(s) && (s[i+1] == '\n' || s[i+1] == '\r') {
				i++
				if s[i] == '\r' {
					i++
				}
				if i < len(s) && s[i] == '\n' {
					i++
				}
				for i < len(s) && (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\r') {
					i++
				}
				continue
			}
			v, n, err := escape(s, i+1)
			if err != nil {
				return "", i, err
			}
			b.WriteString(v)
			i = n + 1
			continue
		}
		if s[i] == '\r' {
			if i+1 < len(s) && s[i+1] == '\n' {
				i++
			}
			b.WriteByte('\n')
			i++
			continue
		}
		if s[i] < 0x20 && s[i] != '\n' && s[i] != '\t' || s[i] == 0x7f {
			return "", i, fmt.Errorf("invalid control character in string")
		}
		b.WriteByte(s[i])
		i++
	}
	return "", len(s), fmt.Errorf("unterminated string")
}

func parseScalar(raw string) (Value, int, error) {
	if raw == "true" || raw == "false" {
		return Value{"bool", raw}, 0, nil
	}
	if raw == "inf" || raw == "+inf" || raw == "-inf" || raw == "nan" || raw == "+nan" || raw == "-nan" {
		return Value{"float", raw}, 0, nil
	}
	clean := strings.ReplaceAll(raw, "_", "")
	if strings.ContainsAny(raw, " \t\r") || raw == "" || strings.Contains(raw, "__") || strings.HasPrefix(raw, "_") || strings.HasSuffix(raw, "_") {
		return Value{}, 0, fmt.Errorf("invalid scalar")
	}
	if strings.HasPrefix(clean, "0x") || strings.HasPrefix(clean, "0o") || strings.HasPrefix(clean, "0b") {
		base := 16
		if clean[1] == 'o' {
			base = 8
		}
		if clean[1] == 'b' {
			base = 2
		}
		if _, err := strconv.ParseInt(clean[2:], base, 64); err != nil {
			return Value{}, 0, fmt.Errorf("invalid integer")
		}
		return Value{"integer", raw}, 0, nil
	}
	if strings.ContainsAny(clean, ".eE") {
		if _, err := strconv.ParseFloat(clean, 64); err != nil || !validFloat(clean) {
			return Value{}, 0, fmt.Errorf("invalid float")
		}
		return Value{"float", raw}, 0, nil
	}
	if _, err := strconv.ParseInt(clean, 10, 64); err != nil || (len(clean) > 1 && (clean[0] == '0' || clean[0] == '+' || clean[0] == '-') && clean[1] == '0' && len(clean) > 2) {
		return Value{}, 0, fmt.Errorf("invalid integer")
	}
	return Value{"integer", raw}, 0, nil
}

func validFloat(s string) bool {
	if strings.HasSuffix(s, ".") || strings.HasPrefix(s, ".") {
		return false
	}
	for i := 0; i < len(s); i++ {
		if s[i] == '_' && (i == 0 || i+1 == len(s) || !isDigit(s[i-1]) || !isDigit(s[i+1])) {
			return false
		}
	}

	if strings.ContainsAny(raw, " \t\r") || raw == "" || !validUnderscores(raw) {
		return Value{}, 0, fmt.Errorf("invalid scalar")
	}
	if strings.HasPrefix(clean, "0x") || strings.HasPrefix(clean, "0o") || strings.HasPrefix(clean, "0b") {
		base := 16
		if clean[1] == 'o' {
			base = 8
		}
		if clean[1] == 'b' {
			base = 2
		}
		n, err := strconv.ParseUint(clean[2:], base, 64)
		if err != nil || n > math.MaxInt64 {
			return Value{}, 0, fmt.Errorf("invalid integer")
		}
		return Value{"integer", strconv.FormatUint(n, 10)}, 0, nil
	}
	if strings.ContainsAny(clean, ".eE") {
		if _, err := strconv.ParseFloat(clean, 64); err != nil || !validFloat(clean) {
			return Value{}, 0, fmt.Errorf("invalid float")
		}
		return Value{"float", raw}, 0, nil
	}
	n, err := strconv.ParseInt(clean, 10, 64)
	if err != nil || (len(clean) > 1 && clean[0] == '0' && clean[1] >= '0' && clean[1] <= '9') {
		return Value{}, 0, fmt.Errorf("invalid integer")
	}
	return Value{"integer", strconv.FormatInt(n, 10)}, 0, nil
}

func validFloat(s string) bool {
	if strings.HasSuffix(s, ".") || strings.HasPrefix(s, ".") {
		return false
	}
	return validUnderscores(s)
}

func validUnderscores(s string) bool {
	for i := 0; i < len(s); i++ {
		if s[i] == '_' && (i == 0 || i+1 == len(s) || !isDigit(s[i-1]) || !isDigit(s[i+1])) { return false }
	}
	return true
}

func isDigit(c byte) bool { return c >= '0' && c <= '9' }

